1	use inkseal::{ParseDigestError, Sha256Digest};
2	use std::env;
3	use std::ffi::OsStr;
4	use std::fs::File;
5	use std::io;
6	use std::path::{Path, PathBuf};
7	use std::process::ExitCode;
8	
9	const USAGE: &str = "Usage: inkseal --version\n       inkseal digest <file>\n       inkseal check-digest <file> <digest>\n       inkseal check-digest-file <file> <digest-file>";
10	
11	fn main() -> ExitCode {
12	    // 使用 args_os 而非 args：命令行参数是操作系统给出的原始字节，
13	    // 在允许非 UTF-8 文件名的系统上这类路径是合法路径，必须原样保留。
14	    let mut args = env::args_os().skip(1);
15	    match args.next() {
16	        Some(ref cmd) if cmd.as_encoded_bytes() == b"--version" && args.next().is_none() => {
17	            emit_success(b"inkseal 0.1.0\n")
18	        }
19	        Some(ref cmd) if cmd.as_encoded_bytes() == b"digest" => {
20	            let (Some(path), None) = (args.next(), args.next()) else {
21	                return emit_error(2, format!("{USAGE}\n").as_bytes());
22	            };
23	            run_digest(Path::new(&path))
24	        }
25	        Some(ref cmd) if cmd.as_encoded_bytes() == b"check-digest" => {
26	            let (Some(path), Some(expected), None) = (args.next(), args.next(), args.next()) else {
27	                return emit_error(
28	                    2,
29	                    format!(
30	                        "inkseal: check-digest requires exactly two arguments: <file> <digest>\n\
31	                         {USAGE}\n"
32	                    )
33	                    .as_bytes(),
34	                );
35	            };
36	            run_check_digest(Path::new(&path), &expected)
37	        }
38	        Some(ref cmd) if cmd.as_encoded_bytes() == b"check-digest-file" => {
39	            let (Some(path), Some(digest_path), None) = (args.next(), args.next(), args.next())
40	            else {
41	                return emit_error(
42	                    2,
43	                    format!(
44	                        "inkseal: check-digest-file requires exactly two arguments: \
45	                         <file> <digest-file>\n\
46	                         {USAGE}\n"
47	                    )
48	                    .as_bytes(),
49	                );
50	            };
51	            run_check_digest_file(Path::new(&path), Path::new(&digest_path))
52	        }
53	        _ => {
54	            // 未知子命令（即便含有非 UTF-8 字节）等用法错误统一走这里。
55	            emit_error(2, format!("{USAGE}\n").as_bytes())
56	        }
57	    }
58	}
59	
60	/// 打开 `path` 并以流式方式读取其全部内容，返回完整摘要。
61	///
62	/// 这是 `digest` 与 `check-digest` 共用的唯一文件访问规则：始终以操作
63	/// 系统给出的原始路径打开文件（用于显示的文字绝不参与访问），以原始
64	/// 字节流式计算摘要——空文件、二进制内容与各种换行形式都按同一条规则
65	/// 处理，内存占用与文件大小无关。文件打不开与读取中途失败是两类不同的
66	/// 失败（见 [`FileAccessError`]）；即使已读入一部分内容，读取失败也绝不
67	/// 返回部分摘要。
68	fn digest_file(path: &Path) -> Result<Sha256Digest, FileAccessError> {
69	    let file = File::open(path)
70	        .map_err(|err| FileAccessError::Open(path.to_path_buf(), err))?;
71	    inkseal::digest_reader(file)
72	        .map_err(|err| FileAccessError::Read(path.to_path_buf(), err))
73	}
74	
75	/// 读取单个文件计算完整摘要时的失败，区分“打不开”与“读取中途失败”,
76	/// 以便两条命令共用同一套提示规则。
77	enum FileAccessError {
78	    /// 文件无法打开；携带原始路径与系统给出的原因。
79	    Open(PathBuf, io::Error),
80	    /// 文件已打开但读取中途失败；已读入的部分内容不产生任何摘要。
81	    Read(PathBuf, inkseal::DigestError),
82	}
83	
84	impl FileAccessError {
85	    /// 渲染为既有的单行错误提示（含末尾换行）：仅在此时把路径做损失性
86	    /// 转换并转义控制字符，显示文字不影响也不回溯到实际访问对象。
87	    fn message(&self) -> String {
88	        match self {
89	            FileAccessError::Open(path, err) => {
90	                format!("inkseal: cannot open '{}': {err}\n", path_display(path))
91	            }
92	            FileAccessError::Read(path, err) => {
93	                format!("inkseal: cannot read '{}': {err}\n", path_display(path))
94	            }
95	        }
96	    }
97	}
98	
99	fn run_digest(path: &Path) -> ExitCode {
100	    match digest_file(path) {
101	        Ok(digest) => {
102	            let mut line = digest.to_hex();
103	            line.push('\n');
104	            emit_success(line.as_bytes())
105	        }
106	        Err(err) => emit_error(1, err.message().as_bytes()),
107	    }
108	}
109	
110	/// 把成功结果一次性完整写到标准输出并立即刷出，返回进程退出码。
111	///
112	/// 成功的含义是**整行结果（含末尾换行）已经真正交到输出端**：仅算出
113	/// 摘要或通过比较并不构成成功，写中途失败或最后的刷新失败（例如标准
114	/// 输出被重定向到只读位置，或管道接收方提前关闭）都必须以退出码 1
115	/// 结束，而不是让 `println!` 的 panic 打印崩溃信息，也不能照常报成功。
116	///
117	/// 输出失败时只在标准错误给出一条以 `inkseal:` 开头的单行提示，保留
118	/// 系统给出的具体原因；不补充用法说明，不把摘要改写到标准错误，也不
119	/// 重试整行输出。标准输出此前可能已经收到结果的前几个字节，这些字节
120	/// 无法也不必撤回。若连这条提示都写不出去，同样静默地以退出码 1
121	/// 结束——报告输出失败的过程自身绝不能再崩溃。
122	fn emit_success(line: &[u8]) -> ExitCode {
123	    match write_stdout_all(line) {
124	        Ok(()) => ExitCode::SUCCESS,
125	        Err(err) => {
126	            // 与失败路径同一条规则：提示本身写不出去也忽略，只需保证
127	            // 退出码为 1，绝不经过会因写失败而 panic 的宏。
128	            let hint = format!("inkseal: unable to write to standard output: {err}\n");
129	            let _ = write_stderr_all(hint.as_bytes());
130	            ExitCode::FAILURE
131	        }
132	    }
133	}
134	
135	/// 失败路径的统一出口：把既有的错误提示（原始字节，含其行结构）尽力
136	/// 写到标准错误，然后以约定的退出码（用法错误 `2`、其余失败 `1`）结束。
137	///
138	/// 提示说明的是**已经发生的失败**：接收方是否还读得到提示，不能改变
139	/// 命令对本次操作的判断。标准错误被接到另一个程序而接收方提前关闭管道、
140	/// 或从一开始就拒绝写入时，`eprintln!` 会在 EPIPE/EBADF 上 panic，使
141	/// 进程以崩溃退出码（101）结束并打出崩溃信息，丢掉原本约定的退出码。
142	/// 这里与 [emit_success] 一样直接走 `write` 系统调用并忽略写失败：
143	/// 已经送出的字节保留，写不出去的部分不补齐、不重试、不改写到标准输出，
144	/// 只保证静默地以 `code` 正常结束。
145	fn emit_error(code: u8, message: &[u8]) -> ExitCode {
146	    let _ = write_stderr_all(message);
147	    ExitCode::from(code)
148	}
149	
150	/// 把 `data` 完整写到给定输出端：成功结果与失败提示共用的唯一交付规则。
151	///
152	/// 只要输出端仍可继续接收，临时中断（EINTR）原地重试、一次只接收部分
153	/// 字节（短写）就续写剩余部分，直到全部字节交付完毕——最终内容完整、
154	/// 顺序不变且没有重复。真正的写入错误结束本次交付并返回该错误；对正数
155	/// 计数的 write 返回 0 没有任何进展，按失败处理而不是空转。`target`
156	/// 只用于“毫无进展”这条合成错误的文字，系统给出的真实错误原样返回。
157	#[cfg(unix)]
158	fn write_fd_all(fd: std::os::fd::RawFd, mut data: &[u8], target: &'static str) -> io::Result<()> {
159	    use std::os::raw::c_void;
160	
161	    unsafe extern "C" {
162	        fn write(fd: std::os::fd::RawFd, buf: *const c_void, count: usize) -> isize;
163	    }
164	
165	    while !data.is_empty() {
166	        let written = unsafe { write(fd, data.as_ptr().cast::<c_void>(), data.len()) };
167	        if written < 0 {
168	            let err = io::Error::last_os_error();
169	            // 临时中断不代表任何字节的命运，原地重试。
170	            if err.kind() == io::ErrorKind::Interrupted {
171	                continue;
172	            }
173	            return Err(err);
174	        }
175	        let n = written as usize;
176	        if n == 0 {
177	            // 对正数计数的 write 返回 0 没有可恢复的含义，停止续写，
178	            // 避免在此空转。
179	            return Err(io::Error::new(
180	                io::ErrorKind::WriteZero,
181	                format!("write to {target} returned no progress"),
182	            ));
183	        }
184	        data = &data[n..];
185	    }
186	    Ok(())
187	}
188	
189	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
190	/// `write_all` 内部已处理短写与 EINTR，语义与 Unix 路径一致。
191	#[cfg(not(unix))]
192	fn write_locked_all(mut handle: impl std::io::Write, data: &[u8]) -> io::Result<()> {
193	    use std::io::Write;
194	
195	    handle.write_all(data)?;
196	    handle.flush()
197	}
198	
199	/// 直接对标准输出的原始文件描述符发起 `write`，绕过标准库 `Stdout`
200	/// 对“输出端不存在/拒绝写入”这类失败的特殊处理——它在某些情况下会把
201	/// 失败（如 fd 以只读方式打开时内核返回的 EBADF）静默报告为成功，导致
202	/// 调用方误以为结果已交付。
203	#[cfg(unix)]
204	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
205	    const STDOUT_FD: std::os::fd::RawFd = 1;
206	    write_fd_all(STDOUT_FD, line, "standard output")
207	}
208	
209	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
210	#[cfg(not(unix))]
211	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
212	    write_locked_all(io::stdout().lock(), line)
213	}
214	
215	/// 直接对标准错误的原始文件描述符发起 `write`，绕过标准库 `Stderr`
216	/// 的行缓冲以及 `eprintln!`/`writeln!` 在写失败时的 panic（宏内部
217	/// `unwrap`）。任何无法继续写入的错误都返回，由调用方决定忽略——
218	/// 失败提示本身绝不能再崩溃。
219	#[cfg(unix)]
220	fn write_stderr_all(message: &[u8]) -> io::Result<()> {
221	    const STDERR_FD: std::os::fd::RawFd = 2;
222	    write_fd_all(STDERR_FD, message, "standard error")
223	}
224	
225	/// 非 Unix 目标：沿用加锁写入并显式刷新；写失败同样由调用方忽略。
226	#[cfg(not(unix))]
227	fn write_stderr_all(message: &[u8]) -> io::Result<()> {
228	    write_locked_all(io::stderr().lock(), message)
229	}
230	
231	/// 解析用户给出的预期摘要。
232	///
233	/// 解析规则完全来自库（[`Sha256Digest::from_hex_bytes`]），与库的
234	/// `FromStr` 以及摘要的再次显示共用同一套实现：必须恰好是 64 个 ASCII
235	/// 十六进制字符（大小写均可），按其表示的 32 字节摘要值比较，不做任何
236	/// 空白裁剪——前缀、空格、末尾换行、长度不对或含非十六进制字符都视为
237	/// 格式错误；参数无法解码为合法文字时，直接按其原始字节校验，同样视为
238	/// 格式错误。这里只负责把库的类型化错误映射为本命令既有的提示文字。
239	fn parse_expected_digest(arg: &OsStr) -> Result<Sha256Digest, String> {
240	    Sha256Digest::from_hex_bytes(arg.as_encoded_bytes()).map_err(|err| match err {
241	        ParseDigestError::InvalidLength(len) => format!(
242	            "expected digest must be exactly 64 ASCII hexadecimal characters, got {len}"
243	        ),
244	        ParseDigestError::InvalidHexChar(_) => {
245	            "expected digest contains a non-hexadecimal character".to_string()
246	        }
247	    })
248	}
249	
250	fn run_check_digest(path: &Path, expected_arg: &OsStr) -> ExitCode {
251	    // 先校验摘要格式；格式不合法时绝不打开文件——即使路径本身也不存在，
252	    // 仍报告摘要格式问题。
253	    let expected = match parse_expected_digest(expected_arg) {
254	        Ok(digest) => digest,
255	        Err(reason) => {
256	            return emit_error(
257	                2,
258	                format!("inkseal: invalid expected digest: {reason}\n{USAGE}\n").as_bytes(),
259	            );
260	        }
261	    };
262	
263	    finish_digest_check(path, expected)
264	}
265	
266	/// 预期摘要已确认合法后，核对 `path` 的实际内容并按既有的唯一一套规则
267	/// 输出：匹配写 `OK\n`（完整交付后以 0 退出）；访问失败报告文件原因；
268	/// 不匹配列出小写的预期与实际摘要。`check-digest` 与
269	/// `check-digest-file` 在拿到合法摘要之后共用本函数，因此两者对待核对
270	/// 文件的原始字节、流式读取、比较与输出规则完全一致。
271	fn finish_digest_check(path: &Path, expected: Sha256Digest) -> ExitCode {
272	    // 与 digest 共用同一条文件访问规则；访问失败是文件问题，
273	    // 绝不能被解释成内容不匹配。
274	    let actual = match digest_file(path) {
275	        Ok(digest) => digest,
276	        Err(err) => return emit_error(1, err.message().as_bytes()),
277	    };
278	
279	    if actual == expected {
280	        emit_success(b"OK\n")
281	    } else {
282	        // 内容不匹配：预期与实际都用库的同一显示规则呈现为
283	        // 64 个小写十六进制字符（大小写混用的输入也规范为小写）。
284	        emit_error(
285	            1,
286	            format!(
287	                "inkseal: digest mismatch for '{}'\n\
288	                 expected: {}\n\
289	                 actual:   {}\n",
290	                path_display(path),
291	                expected.to_hex(),
292	                actual.to_hex()
293	            )
294	            .as_bytes(),
295	        )
296	    }
297	}
298	
299	/// 读取并解析摘要文件时的失败。
300	///
301	/// 前两类是摘要文件本身的访问问题（以 `1` 退出）；[`Malformed`](Self::Malformed)
302	/// 是内容不符合“恰好一份摘要”的格式约定（以 `2` 退出）。三类都必须在
303	/// 待核对文件被访问之前判定，且提示里都要带上摘要文件自己的路径，绝不
304	/// 能把摘要文件的问题改报成待核对文件的访问错误。
305	enum DigestFileError {
306	    /// 摘要文件无法打开（不存在、权限不足等）。
307	    Open(PathBuf, io::Error),
308	    /// 摘要文件已打开但读取中途失败（含路径指向目录时的读取错误）。
309	    Read(PathBuf, io::Error),
310	    /// 摘要文件内容不符合格式约定。
311	    Malformed(PathBuf, DigestFileProblem),
312	}
313	
314	/// 摘要文件内容的具体格式问题，用于给出精确的错误原因。
315	enum DigestFileProblem {
316	    /// 空文件：连一个摘要字符都没有。
317	    Empty,
318	    /// 内容超过“64 个十六进制字符 + 单个 CRLF”的 66 字节上限：
319	    /// 多余字节可能是第二份摘要、文件名或任何附加内容，一律拒绝。
320	    TooLong,
321	    /// 去掉唯一允许的末尾换行后，摘要正文未通过库的严格十六进制解析。
322	    InvalidDigest(ParseDigestError),
323	}
324	
325	impl DigestFileProblem {
326	    /// 渲染为人类可读的具体格式原因（不含路径，路径由调用方添加）。
327	    fn description(&self) -> String {
328	        const RULE: &str = concat!(
329	            "the digest file must contain exactly one digest of 64 ASCII ",
330	            "hexadecimal characters, optionally followed by one LF or CRLF"
331	        );
332	        match self {
333	            DigestFileProblem::Empty => {
334	                format!("{RULE}, but the file is empty")
335	            }
336	            DigestFileProblem::TooLong => {
337	                format!("{RULE}, but the file contains extra bytes beyond that single line")
338	            }
339	            DigestFileProblem::InvalidDigest(ParseDigestError::InvalidLength(len)) => {
340	                format!(
341	                    "{RULE}; the digest text is {len} bytes long (before any trailing newline)"
342	                )
343	            }
344	            DigestFileProblem::InvalidDigest(ParseDigestError::InvalidHexChar(pos)) => {
345	                format!(
346	                    "{RULE}; the digest text contains a non-hexadecimal byte at offset {pos} \
347	                    (only 0-9, a-f and A-F are allowed)"
348	                )
349	            }
350	        }
351	    }
352	}
353	
354	/// 打开摘要文件、读取其（被严格限长的）全部内容并解析为摘要值。
355	///
356	/// 合法文件至多 66 字节：64 个十六进制字符，末尾可带一个 LF 或 CRLF。
357	/// 这里最多读入 67 字节——多出的第 67 字节是“内容超长”的确定性哨兵，
358	/// 因此内存占用恒定，也不必把可能很大的非法文件（例如误指向二进制或
359	/// 第二份摘要）整个读完就能判定格式错误。读取本身失败与内容格式不合法
360	/// 是两类不同的失败，分别映射到 [`DigestFileError`] 的不同变体。
361	fn load_expected_digest_file(path: &Path) -> Result<Sha256Digest, DigestFileError> {
362	    use std::io::Read as _;
363	
364	    let file = File::open(path)
365	        .map_err(|err| DigestFileError::Open(path.to_path_buf(), err))?;
366	
367	    let mut content = Vec::with_capacity(67);
368	    file.take(67)
369	        .read_to_end(&mut content)
370	        .map_err(|err| DigestFileError::Read(path.to_path_buf(), err))?;
371	
372	    parse_digest_file_content(&content)
373	        .map_err(|problem| DigestFileError::Malformed(path.to_path_buf(), problem))
374	}
375	
376	/// 摘要文件内容的唯一解析规则。
377	///
378	/// 与 `check-digest` 的摘要参数不同，摘要文件允许结尾带一个换行：内容
379	/// 要么恰好是 64 个十六进制字符，要么在其后紧跟一个 LF 或 CRLF。除此之外
380	/// 不做任何裁剪或修正——空文件、首尾空格、单独的 CR、额外空行、第二份
381	/// 摘要、附带的文件名、`0x` 前缀或非 ASCII 字节都属于格式错误。剥离唯一
382	/// 允许的行结束后，正文仍必须通过库的严格解析
383	/// （[`Sha256Digest::from_hex_bytes`]），其严格格式不在此放宽。
384	fn parse_digest_file_content(content: &[u8]) -> Result<Sha256Digest, DigestFileProblem> {
385	    if content.is_empty() {
386	        return Err(DigestFileProblem::Empty);
387	    }
388	    if content.len() > 66 {
389	        return Err(DigestFileProblem::TooLong);
390	    }
391	
392	    // 仅当 LF 是最后一个字节时剥离它；剥到 LF 后，再仅当 CR 紧接在它
393	    // 前面（即结尾确为 CRLF）时剥离该 CR。顺序保证：单独的 CR、CRLF
394	    // 之外的任何尾随字节都不会被裁掉——例如 "\n\r" 的末字节是 CR，
395	    // 第一步就不匹配，整体按长度错误拒绝。
396	    let mut hex: &[u8] = content;
397	    if let Some(rest) = hex.strip_suffix(b"\n") {
398	        hex = rest;
399	        if let Some(rest) = hex.strip_suffix(b"\r") {
400	            hex = rest;
401	        }
402	    }
403	
404	    Sha256Digest::from_hex_bytes(hex).map_err(DigestFileProblem::InvalidDigest)
405	}
406	
407	fn run_check_digest_file(path: &Path, digest_path: &Path) -> ExitCode {
408	    // 先完整处理摘要文件：在它被成功打开、读取并确认格式合法之前，
409	    // 绝不访问待核对文件——即使待核对文件不存在，也不得改报它的错误。
410	    let expected = match load_expected_digest_file(digest_path) {
411	        Ok(digest) => digest,
412	        Err(DigestFileError::Open(p, err)) => {
413	            return emit_error(
414	                1,
415	                format!(
416	                    "inkseal: cannot open digest file '{}': {err}\n",
417	                    path_display(&p)
418	                )
419	                .as_bytes(),
420	            );
421	        }
422	        Err(DigestFileError::Read(p, err)) => {
423	            return emit_error(
424	                1,
425	                format!(
426	                    "inkseal: cannot read digest file '{}': {err}\n",
427	                    path_display(&p)
428	                )
429	                .as_bytes(),
430	            );
431	        }
432	        Err(DigestFileError::Malformed(p, problem)) => {
433	            return emit_error(
434	                2,
435	                format!(
436	                    "inkseal: malformed digest file '{}': {}\n{USAGE}\n",
437	                    path_display(&p),
438	                    problem.description()
439	                )
440	                .as_bytes(),
441	            );
442	        }
443	    };
444	
445	    // 摘要文件合法后才打开待核对文件；其后的访问、比较与输出规则与
446	    // check-digest 完全一致（共用 finish_digest_check）。
447	    finish_digest_check(path, expected)
448	}
449	
450	/// 生成可安全输出到标准错误的路径文本：不可解码的字节以替换字符
451	/// （U+FFFD）呈现，控制字符转义为可见写法。该文本只用于显示。
452	fn path_display(path: &Path) -> String {
453	    let lossy = path.to_string_lossy();
454	    if !lossy.contains(char::is_control) {
455	        return lossy.into_owned();
456	    }
457	    let mut out = String::with_capacity(lossy.len());
458	    for ch in lossy.chars() {
459	        match ch {
460	            '\t' => out.push_str("\\t"),
461	            '\n' => out.push_str("\\n"),
462	            '\r' => out.push_str("\\r"),
463	            c if c.is_control() => {
464	                use std::fmt::Write as _;
465	                let _ = write!(out, "\\u{{{:x}}}", c as u32);
466	            }
467	            c => out.push(c),
468	        }
469	    }
470	    out
471	}
