        let cases: Vec<Vec<&OsStr>> = vec![
            vec![OsStr::new("digest"), missing.as_os_str()],
            vec![OsStr::new("digest"), subdir.as_os_str()],
            vec![
                OsStr::new("check-digest"),
                missing.as_os_str(),
                OsStr::new(ABC_HEX),
