            vec![
                OsStr::new("check-digest"),
                subdir.as_os_str(),
                OsStr::new(ABC_HEX),
            ],
            vec![
                OsStr::new("check-digest"),
                file.as_os_str(),
                OsStr::new(empty_hex),
