            // 摘要文件本身无法打开：退出码 1，与待核对文件无关。
            vec![
                OsStr::new("check-digest-file"),
                file.as_os_str(),
                missing_digest.as_os_str(),
            ],
            // 摘要文件指向目录（读取失败）：退出码 1。
            vec![
                OsStr::new("check-digest-file"),
                file.as_os_str(),
                digest_subdir.as_os_str(),
