1997	// ── 临时受阻后完整交付（EINTR 与短写）─────────────────────────────────────────
1998	//
1999	// 接收方仍可继续写入时，对输出端的 write 可能因信号临时中断（EINTR，一个
2000	// 字节都没送出），也可能一次只接收部分字节（短写）。命令必须原地重试中断、
2001	// 续写剩余部分，最终交付的内容与无中断时完全相同：每个字节恰好一次、顺序
2002	// 不变、末尾换行不丢失。这类“临时受阻后恢复”的序列无法从父进程一侧确定
2003	// 性地制造（阻塞写会写满才返回，EINTR 需要子进程安装信号处理器），因此
2004	// 用 LD_PRELOAD 垫片拦截子进程的 write，按脚本逐步注入中断、短写、零进展
2005	// 与不可恢复错误，再核对交付内容与退出状态。
2006	#[cfg(target_os = "linux")]
2007	mod write_retry {
2008	    use super::*;
2009	    use std::sync::OnceLock;
2010	
2011	    /// LD_PRELOAD 垫片源码：拦截子进程对标准输出（fd 1）与标准错误（fd 2）
2012	    /// 的 write 调用，按 INKSEAL_WRITE_SHIM 环境变量给出的逗号分隔脚本
2013	    /// 逐步执行，脚本耗尽后按真实 write 透传。步骤：
2014	    /// `i` = 返回 EINTR（不送出任何字节）；`sN` = 最多写 N 字节的短写；
2015	    /// `z` = 尚有内容待写却返回 0（毫无进展）；`eN` = 返回 errno 为 N 的错误。
2016	    ///
2017	    /// 垫片自身发起写时直接走 write 系统调用，绕开对 write 符号的拦截，
2018	    /// 否则透传分支会递归进入自己。垫片不引入任何 crate 依赖，测试运行时
2019	    /// 用 rustc 编译为 cdylib。
