2035	    STEPS
2036	        .get_or_init(|| {
2037	            std::env::var("INKSEAL_WRITE_SHIM")
2038	                .unwrap_or_default()
2039	                .split(',')
2040	                .filter(|token| !token.is_empty())
2041	                .map(|token| {
2042	                    if token == "i" {
2043	                        Step::Intr
2044	                    } else if token == "z" {
2045	                        Step::Zero
2046	                    } else if let Some(n) = token.strip_prefix('s') {
2047	                        Step::Short(n.parse().expect("short-write length"))
2048	                    } else if let Some(e) = token.strip_prefix('e') {
2049	                        Step::Errno(e.parse().expect("errno"))
