248	    impl<'a> ChunkedReader<'a> {
249	        fn new(data: &'a [u8], chunk_sizes: &'a [usize]) -> Self {
250	            ChunkedReader { data, pos: 0, chunk_sizes, chunk_index: 0 }
251	        }
