293	        // 每次只给少量字节（1 字节），读取器必须被持续读取直到报告结束。
294	        let one_byte = digest_reader(ChunkedReader::new(&data, &[1])).unwrap();
295	        // 每次少量但不等的字节数。
296	        let small_uneven = digest_reader(ChunkedReader::new(&data, &[1, 2, 3, 5, 7])).unwrap();
297	        // 较大片段。
