497	    #[test]
498	    fn digest_representations_express_the_same_value() {
499	        let digest = digest_reader(&b"abc"[..]).unwrap();
500	        let hex = digest.to_hex();
501	
502	        // 原始字节与十六进制文本表达同一个值。
503	        let mut from_bytes = String::with_capacity(64);
