toolUseResult.newString:
    #[test]
    fn read_failure_does_not_modify_input_or_create_result_files() {
        let dir = TestDir::new("read-fail-sideeffects");
        let path = dir.write_file(OsStr::new("trap.bin"), &trap_content());
